package org.bramble.wallet.errors

import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * The port of the extension's `friendlyError` against what the extension itself answers
 * ([FriendlyErrorVectors], generated by running it): the swap, revoke and multisig refusals the
 * core writes, and one raw string per branch of the classifier, in its order.
 */
class FriendlyErrorTest {
    @Test
    fun matchesTheExtension() {
        FriendlyErrorVectors.cases.forEach { (raw, shown) -> assertEquals("raw: $raw", shown, friendlyError(raw)) }
    }

    @Test
    fun plumbingReadsTheContext() {
        assertEquals("Couldn't swap.", friendlyError("unknown account", "Couldn't swap."))
        assertEquals("Couldn't swap.", friendlyError("", "Couldn't swap."))
        assertEquals("Already a sentence.", friendlyError("Already a sentence.", "Couldn't swap."))
    }
}
